package com.casegen.ai.proposal.review;

import static org.junit.jupiter.api.Assertions.*;
import com.casegen.ai.provider.AiProviderResult;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

class AiReviewResultParserTest {
    private final AiReviewResultParser parser=new AiReviewResultParser(JsonMapper.builder().build());
    @Test void parsesCompleteMixedReviewAndProviderAudit(){String id=UUID.randomUUID().toString();String json="""
        {"reviewTitle":"Inventario","summary":"Mejoras","items":[
        {"clientRef":"detalle","proposalType":"ADD_CLASSIFIER","title":"Detalle","rationale":"Necesario","dependencies":[],"payload":{"name":"DetalleMovimiento","documentation":null,"packageId":null,"kind":"CLASS","visibility":"PUBLIC","abstractClassifier":false,"active":false}},
        {"clientRef":"sku","proposalType":"ADD_ATTRIBUTE","title":"SKU","rationale":"Identifica","dependencies":[],"payload":{"ownerRef":{"elementId":"%s"},"name":"sku","documentation":null,"visibility":"PRIVATE","typeKind":"PRIMITIVE","primitiveType":"STRING","typeClassifierRef":null,"lowerBound":1,"upperBound":1,"staticProperty":false,"readOnly":false,"derived":false}},
        {"clientRef":"rel","proposalType":"ADD_ASSOCIATION","title":"Relacionar","rationale":"Traza","dependencies":["detalle"],"payload":{"name":null,"documentation":null,"packageId":null,"firstEnd":{"classifierRef":{"elementId":"%s"},"roleName":null,"lowerBound":1,"upperBound":1,"navigable":true,"aggregation":"NONE","ownership":"ASSOCIATION"},"secondEnd":{"classifierRef":{"proposalRef":"detalle"},"roleName":null,"lowerBound":0,"upperBound":null,"navigable":false,"aggregation":"COMPOSITE","ownership":"ASSOCIATION"}}}
        ]}
        """.formatted(id,id);AiReviewResult result=parser.parse(provider(json));assertEquals(3,result.items().size());assertEquals("GEMINI",result.generatedByProvider());assertInstanceOf(ReviewAddClassifierPayload.class,result.items().get(0).payload());assertInstanceOf(ReviewAddAttributePayload.class,result.items().get(1).payload());assertInstanceOf(ReviewAddAssociationPayload.class,result.items().get(2).payload());}
    @Test void parsesJsonFence(){assertEquals("Review",parser.parse(provider("```json\n"+single()+"\n```" )).reviewTitle());}
    @Test void rejectsUnknownFieldsAndInvalidElementRefs(){assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(single().replace("\"summary\":\"Summary\"","\"summary\":\"Summary\",\"extra\":true"))));String id=UUID.randomUUID().toString();assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(single().replace("\"name\":\"Product\"","\"name\":\"Product\",\"id\":\""+id+"\""))));assertThrows(IllegalArgumentException.class,()->new ReviewElementRef(UUID.randomUUID(),"new-one"));}
    @Test void rejectsDuplicateRefsSelfAndDuplicateDependencies(){String duplicate=single().replace("]}",","+singleItem("product")+"]}");assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(duplicate)));String self=single().replace("\"dependencies\":[]","\"dependencies\":[\"product\"]");assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(self)));String repeated=single().replace("\"dependencies\":[]","\"dependencies\":[\"other\",\"other\"]");assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(repeated)));}
    @Test void rejectsMoreThanFifteenAndPerTypeLimits(){List<String> items=new ArrayList<>();for(int i=0;i<16;i++)items.add(singleItem("c"+i));assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(root(items))));items.clear();for(int i=0;i<6;i++)items.add(singleItem("c"+i));assertThrows(AiReviewGenerationException.class,()->parser.parse(provider(root(items))));}
    @Test void parsesRealBalancedTwelveItemReviewWithNewClassifierReferences(){String existing=UUID.randomUUID().toString();List<String> items=new ArrayList<>();items.add(singleItem("detalle-movimiento").replace("\"Product\"","\"DetalleMovimiento\""));items.add(attributeItem("detalle-cantidad","{\"proposalRef\":\"detalle-movimiento\"}","cantidad",List.of("detalle-movimiento")));for(int i=1;i<=5;i++)items.add(attributeItem("atributo-"+i,"{\"elementId\":\""+existing+"\"}","campo"+i,List.of()));for(int i=1;i<=5;i++)items.add(associationItem("asociacion-"+i,existing));AiReviewResult result=parser.parse(provider(root(items)));assertEquals(12,result.items().size());assertEquals(1,result.items().stream().filter(i->i.proposalType()==AiReviewProposalType.ADD_CLASSIFIER).count());assertEquals(6,result.items().stream().filter(i->i.proposalType()==AiReviewProposalType.ADD_ATTRIBUTE).count());assertEquals(5,result.items().stream().filter(i->i.proposalType()==AiReviewProposalType.ADD_ASSOCIATION).count());ReviewAddAttributePayload payload=(ReviewAddAttributePayload)result.items().get(1).payload();assertEquals("detalle-movimiento",payload.ownerRef().proposalRef());assertNull(payload.ownerRef().elementId());}
    private String single(){return root(List.of(singleItem("product")));}
    private String root(List<String> items){return "{\"reviewTitle\":\"Review\",\"summary\":\"Summary\",\"items\":["+String.join(",",items)+"]}";}
    private String singleItem(String ref){return "{\"clientRef\":\""+ref+"\",\"proposalType\":\"ADD_CLASSIFIER\",\"title\":\"Title\",\"rationale\":\"Reason\",\"dependencies\":[],\"payload\":{\"name\":\"Product\",\"documentation\":null,\"packageId\":null,\"kind\":\"CLASS\",\"visibility\":\"PUBLIC\",\"abstractClassifier\":false,\"active\":false}}";}
    private String attributeItem(String ref,String owner,String name,List<String> dependencies){return "{\"clientRef\":\""+ref+"\",\"proposalType\":\"ADD_ATTRIBUTE\",\"title\":\"Attribute\",\"rationale\":\"Reason\",\"dependencies\":"+dependencies.stream().map(d->"\""+d+"\"").toList()+",\"payload\":{\"ownerRef\":"+owner+",\"name\":\""+name+"\",\"documentation\":null,\"visibility\":\"PRIVATE\",\"typeKind\":\"PRIMITIVE\",\"primitiveType\":\"STRING\",\"typeClassifierRef\":null,\"lowerBound\":1,\"upperBound\":1,\"staticProperty\":false,\"readOnly\":false,\"derived\":false}}";}
    private String associationItem(String ref,String existing){return "{\"clientRef\":\""+ref+"\",\"proposalType\":\"ADD_ASSOCIATION\",\"title\":\"Association\",\"rationale\":\"Reason\",\"dependencies\":[\"detalle-movimiento\"],\"payload\":{\"name\":null,\"documentation\":null,\"packageId\":null,\"firstEnd\":{\"classifierRef\":{\"elementId\":\""+existing+"\"},\"roleName\":null,\"lowerBound\":1,\"upperBound\":1,\"navigable\":true,\"aggregation\":\"NONE\",\"ownership\":\"ASSOCIATION\"},\"secondEnd\":{\"classifierRef\":{\"proposalRef\":\"detalle-movimiento\"},\"roleName\":null,\"lowerBound\":0,\"upperBound\":null,\"navigable\":false,\"aggregation\":\"COMPOSITE\",\"ownership\":\"ASSOCIATION\"}}}";}
    private AiProviderResult provider(String json){return new AiProviderResult(json,"GEMINI","model","STOP");}
}
